mutations.after:
for (index, slot) in frame.writes[..frame.count].iter().enumerate() {
    let value = if index >= 2 && index < 2 + count {
        let source_index = count - 1 - (index - 2);
        let offset = step(operands.input_sp, source_index as u64 * u64::from(width.bytes()), context.stack_width());
        read_stack(context, image, offset, width, observe)?
    } else { slot.value };
    image
        .write(slot.address, slot.width, value)
        .expect("admitted private gate frame write");
}

